80: /// same shape. Field order follows the first item's serialized key order;
81: /// scalar values (string/number/bool/null) map directly to [`Value`],
82: /// anything else (a nested object or array) is serialized to a compact JSON
83: /// string and carried as `Value::Str` — lossless, never a hard error. Items
84: /// that don't serialize to a JSON object (e.g. a bare number or string slice)
85: /// produce an empty row rather than panicking.
86: ///
87: /// Requires the `serde` feature.
88: ///
89: /// ```rust
90: /// # #[cfg(feature = "serde")] {
91: /// use michi::toon;
92: ///
93: /// #[derive(serde::Serialize)]
94: /// struct Issue { number: u64, title: String, state: String }
95: ///
96: /// let issues = vec![Issue { number: 51815, title: "Bug".to_string(), state: "open".to_string() }];
97: /// let opts = toon::list("issues", &issues);
98: /// let out = toon::render_toon(&opts);
99: /// assert!(out.starts_with("issues[1]{number,title,state}:\n"));
100: /// # }
101: /// ```
