104: pub fn list<T: serde::Serialize>(type_name: impl Into<String>, items: &[T]) -> ToonOptions {
105:     let mut fields: Vec<String> = Vec::new();
106:     let mut rows: Vec<Vec<Value>> = Vec::with_capacity(items.len());
107:     for item in items {
108:         let obj = match serde_json::to_value(item) {
109:             Ok(serde_json::Value::Object(map)) => map,
110:             _ => serde_json::Map::new(),
111:         };
112:         if fields.is_empty() && !obj.is_empty() {
113:             fields = obj.keys().cloned().collect();
